package config

import "math"

// Monk tuning. Everything the monk kit reads lives here so the class can be
// rebalanced from one file.
//
// Chi is the monk's resource. It reuses the mana meter (persisted as
// manacur/manamax) but follows different rules: it is generated by landing
// attacks, dodging, and meditating; it regenerates passively only while the
// monk is in a meditative trance; and it bleeds away once the monk has been
// out of combat for a while.
const (
	// Tier gates.
	// Flurry comes early (2026-10-14: was MajorAbilityTier) so a monk learns
	// the chi loop before touch of death adds a second use for it.
	MonkLeapTier     = 5
	MonkSweepTier    = 5
	MonkFlurryTier   = 5
	MonkTodTier      = MajorAbilityTier
	MonkLongLeapTier = MajorAbilityTier
	MonkDodgeTier    = 15
	MonkFeintTier    = 15
	// FeintEnabled registers the feint command. Off since 2026-10-14: with the
	// taunt moved to sweep, feint was a defensive button pressed every other
	// round while offtanking, and monks already have plenty to manage. The
	// code is kept so it can be switched back on.
	FeintEnabled = false
	// From this tier a monk's discipline blunts vital and critical strikes.
	MonkIronBodyTier = 15
	// From this tier, afflictions aimed at a meditating monk must beat a save.
	MonkMeditateSaveTier = MajorAbilityTier

	MonkSpellCostDivisor = 2 // monk spells cost mana/2, minimum 1
	ChiPerHit            = 3 // flat chi per landed hit ... (2 until 2026-09-27)
	ChiPerHitPieDiv      = 5 // ... plus pie/5, never less than ChiPerHitPieMin (was pie/8)
	ChiPerHitPieMin      = 1
	DodgeChiGain         = 3 // chi per successful passive dodge
	CritChiMultiplier    = 3 // a critical hit builds this many hits' worth of chi
	// Character ticks are 8s apart. The grace covers the first two ticks
	// after the last hit as a reprieve, so a short walk to the next fight
	// keeps its chi; the bleed starts on the third tick.
	ChiDecayGraceSeconds = 20
	ChiDecayPercent      = 10 // of max chi, per tick, once out of combat
	ChiDecayFloorCap     = 10 // out of combat chi settles at min(tier, this): decays down to it, recovers up to it (recovery since 2026-10-15)
	ChiGainCapPercent    = 15 // no single chi award exceeds this share of max chi; only bites on tiny tier 1-3 pools (was 10 until 2026-09-27)

	// Meditate: instant restore of (base + pie/div + tier*perTier)% of each pool,
	// then a trance that halts chi decay and boosts chi generation. Meditate
	// recharges over MeditateChargeTime: the restore and the trance length
	// scale with the share of it that has passed since the last cast, so
	// casting early trades power for timing without adding to the total. It
	// can be used again once the trance has ended and at least
	// MeditateMinCharge seconds have passed; the affliction purge happens on
	// every cast at full strength. (2026-10-13: was a flat 300s cooldown with
	// a full restore and trance every time.)
	MeditateChargeTime      = 300 // seconds to recover a full meditate
	MeditateMinCharge       = 30  // seconds since the last cast before meditate can be used
	MeditateBasePercent     = 20
	MeditatePieDiv          = 3
	MeditatePercentPerTier  = 1
	MeditateBaseDuration    = 60 // seconds
	MeditateDurationPerTier = 5
	MeditateChiMultiplier   = 1.5
	// While the trance holds, chi regenerates each tick like any caster's
	// mana (ManaRegen in regen.go), scaled by this. Outside the trance chi
	// never regenerates, so this is how a monk refills for utility spells
	// between fights.
	MeditateChiRegenMod = 0.5
	// Meditate also clears poison, disease, blindness and drunkenness on cast.
	// While the trance holds, a monk of MonkMeditateSaveTier or higher rolls
	// to shrug off a new affliction:
	//   base + (tier - attacker level)*perLevelDiff + (tier - saveTier) + con/conDiv, capped.
	MeditateSaveBase         = 50
	MeditateSavePerLevelDiff = 2
	MeditateSaveConDiv       = 2
	MeditateSaveCap          = 90

	// Flurry: a stance that spends chi every attack round for extra swings.
	// A round costs 6 chi below Expert and 8 from Expert up (was 5/7 until
	// 2026-09-26, then 8/10 until 2026-10-02).
	FlurryChiCostBase   = 6
	FlurryChiCostExpert = 8
	FlurryExpertSkill   = 7
	FlurryMaxDuration   = 3600 // safety expiry for the stance, seconds
	// Flurry swings after the first take the fighter's multi attack miss
	// penalty and floor (FollowUpMissChance), but the penalty never exceeds
	// FlurryMaxMissPenalty: monks fight at low hand-to-hand skill, where the
	// fighter's 35 would land on top of a base that dex can't yet floor.
	// (2026-10-13: was a flurry-only 15 through Expert and 10 from Specialist;
	// 2026-10-14: cap added with the fighter penalty going 25 -> 35.)
	FlurryMaxMissPenalty = 25

	// Leap strike.
	LeapFreeDistance = 2  // squares closable at no chi cost
	LongLeapChiCost  = 10 // chi for a leap beyond LeapFreeDistance
	LeapTimer        = 30 // cooldown seconds; 0 means none beyond the combat round

	// Sweep: a full attack round that stuns and taunts when it lands. The stun
	// costs the monk no damage (circle spends the round), so the timer is long:
	// a 12s stun every 60s denies the mob roughly one attack in eight.
	// (2026-10-13: was 30s.)
	SweepTimer = 60
	SweepStuns = 12 // seconds

	// Touch of death. The cooldown starts at TodTimerBase and drops
	// TodTimerPerTier seconds for every tier past TodTimerScaleTier, never
	// below TodTimerMin. (2026-10-01: was 600 dropping 60 a tier to 300; in
	// play a touch is often skipped, e.g. after a crit, and chi gates it anyway.)
	TodTimerBase      = 300
	TodTimerScaleTier = 15
	TodTimerPerTier   = 24
	TodTimerMin       = 180
	// A touch that misses entirely goes on this shorter, flat cooldown instead.
	TodMissTimer = 120
	// R, the chi commitment the touch is measured against: base + tier*perTier.
	TodReferenceBase    = 10
	TodReferencePerTier = 4
	// Kill chance = scale * c * (1 - h)^2: quadratic in the damage already
	// done, linear in chi committed. The scale starts at TodChanceScale and
	// grows TodChanceScalePerTier for every tier past MonkTodTier, so the touch
	// matures with the monk: at full chi the cap sits near 35% health at tier
	// 10 and near 42% at tier 20. (2026-10-01: was 1.5 * (c - h)^2.)
	TodChanceScale        = 2.0
	TodChanceScalePerTier = 0.05
	TodVulnerableChance   = 0.5 // the monk is told a target looks vulnerable once the odds reach this
	TodMaxChance          = 0.85
	// A touch that lands but fails to kill still tears out a share of the
	// target's max hit points (not remaining, so the blow holds its weight as
	// the target weakens) plus a few unarmed blows, and it ignores armor. The
	// share scales linearly with chi commitment: TodFailMinPercent for a token
	// spend, TodFailMaxPercent for a full R.
	TodFailMinPercent = 5
	TodFailMaxPercent = 25
	TodFailHits       = 1
	TodHitPieDiv      = 3  // miss chance -= pie/3 (2026-10-15: was pie/4)
	TodMissPenalty    = 30 // extra miss over a regular swing, less tier/TodMissTierDiv
	TodMissTierDiv    = 2
	TodMissRefund     = 0.5 // share of the committed chi returned when the touch whiffs

	// Passive dodge and feint. Feint is a full attack round (flurried if the
	// stance is up, at the normal flurry chi cost) with every swing scaled by
	// FeintDamageMultiplier. It costs no chi of its own; an unflurried feint
	// builds chi like any landed hit.
	MonkDodgeBase         = 5
	MonkDodgePerDex       = 0.5
	MonkDodgePerSkill     = 2
	MonkDodgeCap          = 60
	BreathDodgeMultiplier = 0.5 // a dodged breath weapon still lands, at this share of its damage
	FeintDamageMultiplier = 0.5
	FeintDodgeBonus       = 25
	FeintCharges          = 2
	FeintTimer            = 16
	FeintSafetyDuration   = 60 // seconds before unused feint charges lapse

	// Chi ward: from MonkMagicResistTier a monk's chi turns aside
	// MonkMagicResistBase + con/MonkMagicResistConDiv percent of magic damage
	// (capped at MonkMagicResistCap), after every other resist. It costs a
	// chi for every ChiWardDamagePerChi damage turned aside, rounded to the
	// nearest chi, and stops when the chi runs out. Priced at about half a
	// monk's vigor (1 chi for 17-22 stamina) because it needs no cast.
	MonkMagicResistTier   = MajorAbilityTier
	MonkMagicResistBase   = 10
	MonkMagicResistConDiv = 5
	MonkMagicResistCap    = 19
	ChiWardDamagePerChi   = 10

	// Natural armor.
	MonkArmorPerLevel = 15
	ConMonkArmor      = 2

	// Iron body: vital and critical multipliers against a monk drop by a
	// share of the monk's tier. At 20 dex and tier 15 a vital goes
	// 1.8 -> 1.65 and a critical 2.7 -> 2.475; at tier 25, 1.55 and 2.325.
	// Doubles are untouched.
	MonkVitalReductionPerTier    = 0.01
	MonkCriticalReductionPerTier = 0.015

	// Unarmed damage: base + ceil(str/45 * base) + MonkDamageDice d(base/MonkRollDivisor) - MonkDamageCut(tier),
	// where base is the tier's max weapon damage over MonkDamageDivisor.
	// Three dice keep the roll bell-shaped, so the spread feels tighter than
	// its range. The flat cut is a large share of a low-tier hit and a small
	// share of a high-tier one, so the monk lands near three quarters of a
	// geared melee hit from tier 5 up instead of drifting down with level
	// (2026-09-27: was 2 dice with no cut). From MonkFullCutTier the cut tapers
	// off so high tiers keep up with weapon drops (2026-10-01:
	// was 8 at every tier; 2026-10-13: 8/6 -> 6/4 after low-tier damage
	// complaints; 2026-10-14: gate split from MonkFlurryTier when flurry moved
	// to tier 5; 2026-10-26: was 6 from MonkFullCutTier, now tapers to 0 so
	// monks keep pace with the raised tier 10+ weapon drops).
	MonkDamageDivisor        = 2
	MonkRollDivisor          = 3
	MonkDamageDice           = 3
	MonkDamageFlatCut        = 4
	MonkFullCutTier          = MajorAbilityTier
	MonkCutTaperTiersPerStep = 2 // from MonkFullCutTier the cut drops 1 every this many tiers
	MonkDamageFloor          = 1
)

// MonkDamageCut is the flat cut taken off a monk's unarmed hit at a tier: the
// full cut below MonkFullCutTier, then 1 less every MonkCutTaperTiersPerStep
// tiers until it is gone at tier 18.
func MonkDamageCut(tier int) int {
	if tier < MonkFullCutTier {
		return MonkDamageFlatCut
	}
	return max(0, MonkDamageFlatCut-(tier-MonkFullCutTier)/MonkCutTaperTiersPerStep)
}

// MonkVitalReduction is how much a monk of the given tier shaves off an
// incoming vital strike multiplier; zero below MonkIronBodyTier.
func MonkVitalReduction(tier int) float64 {
	if tier < MonkIronBodyTier {
		return 0
	}
	return float64(tier) * MonkVitalReductionPerTier
}

// MonkCriticalReduction is the same for critical strikes.
func MonkCriticalReduction(tier int) float64 {
	if tier < MonkIronBodyTier {
		return 0
	}
	return float64(tier) * MonkCriticalReductionPerTier
}

// MonkMagicResistPercent is the share of magic damage a monk's chi ward turns
// aside at the given constitution.
func MonkMagicResistPercent(con int) int {
	return min(MonkMagicResistCap, MonkMagicResistBase+con/MonkMagicResistConDiv)
}

// ChiWard is how much of a magic hit (already past every other resist) a
// monk's chi turns aside, and the chi that costs, given the ward percentage
// and the chi on hand. Cost is the damage over ChiWardDamagePerChi rounded to
// the nearest chi, so turning aside 1-4 is free; with no chi there is no ward.
func ChiWard(damage int, percent int, chi int) (absorbed int, cost int) {
	if damage <= 0 || chi <= 0 {
		return 0, 0
	}
	absorbed = damage * percent / 100
	if most := chi*ChiWardDamagePerChi + ChiWardDamagePerChi/2 - 1; absorbed > most {
		absorbed = most
	}
	return absorbed, (absorbed + ChiWardDamagePerChi/2) / ChiWardDamagePerChi
}

// MonkNaturalArmor is a monk's armor before spell modifiers. The tier and
// flat con terms form the base, and con then adds the same percentage bonus
// on top that every other class gets on worn armor.
func MonkNaturalArmor(tier int, con int) int {
	base := tier*MonkArmorPerLevel + con*ConMonkArmor
	return base + int(float64(con)*ConArmorMod*float64(base))
}

// MonkUnarmedBase is the fixed portion of a monk's hit at a tier; the rolled
// portion is MonkDamageDice dice of MonkUnarmedRollSides.
func MonkUnarmedBase(tier int) int {
	return MaxWeaponDamage[tier] / MonkDamageDivisor
}

// MonkUnarmedRollSides is the sides on each rolled die of a monk's hit.
func MonkUnarmedRollSides(tier int) int {
	return MonkUnarmedBase(tier) / MonkRollDivisor
}

// MonkUnarmedRange is the lowest and highest hit a monk can land at a tier
// and strength, before surge or damage modifiers.
func MonkUnarmedRange(tier int, str int) (int, int) {
	base := MonkUnarmedBase(tier)
	fixed := base + int(math.Ceil(float64(str)/45*float64(base))) - MonkDamageCut(tier)
	lo, hi := fixed+MonkDamageDice, fixed+MonkDamageDice*MonkUnarmedRollSides(tier)
	if lo < MonkDamageFloor {
		lo = MonkDamageFloor
	}
	if hi < MonkDamageFloor {
		hi = MonkDamageFloor
	}
	return lo, hi
}

// FlurryMinSkill is the unarmed skill level a flurry swings at when the monk's
// own skill is lower: Adept. (2026-10-13: was Ace.)
const FlurryMinSkill = 6

// FlurryChiCost is the chi a flurried attack round costs at an unarmed skill level.
func FlurryChiCost(skill int) int {
	if skill >= FlurryExpertSkill {
		return FlurryChiCostExpert
	}
	return FlurryChiCostBase
}

// MonkFlurryFor returns the swing multipliers for a flurried round. Flurry
// follows the fighter multi-attack table for the monk's unarmed skill, all
// five Grandmaster swings included, except that a monk below Adept still
// swings as an Adept. (2026-10-13: flurry was capped at three swings.)
func MonkFlurryFor(skill int) []float64 {
	if skill < FlurryMinSkill {
		skill = FlurryMinSkill
	}
	if mults, ok := MultiAttackMultipliers[skill]; ok {
		return mults
	}
	return []float64{1}
}

// MonkMaxChi is the monk's chi pool at a tier and piety: the shared mana
// pool formula, keyed on piety.
func MonkMaxChi(tier int, pie int) int {
	return CalcMana(tier, 0, pie, MONK)
}

// ChiPerHitFor is the chi a monk with the given piety earns per landed hit.
func ChiPerHitFor(pie int) int {
	bonus := pie / ChiPerHitPieDiv
	if bonus < ChiPerHitPieMin {
		bonus = ChiPerHitPieMin
	}
	return ChiPerHit + bonus
}

// ChiGainCap is the most chi one award can add to a pool of the given size.
func ChiGainCap(max int) int {
	cap := max * ChiGainCapPercent / 100
	if cap < 1 {
		return 1
	}
	return cap
}

// ChiDecayFloor is the chi an out-of-combat monk settles at: tier, capped at
// ChiDecayFloorCap. Decay stops there and a lower pool recovers up to it, so
// there is always enough for a basic spell or an opening long leap.
func ChiDecayFloor(tier int) int {
	if tier > ChiDecayFloorCap {
		return ChiDecayFloorCap
	}
	return tier
}

// ChiDecayAmount is how much chi bleeds away per tick out of combat.
func ChiDecayAmount(max int) int {
	amount := max * ChiDecayPercent / 100
	if amount < 1 {
		return 1
	}
	return amount
}

// MeditateRestorePercent is the share of each pool meditate restores on cast.
func MeditateRestorePercent(tier int, pie int) int {
	return MeditateBasePercent + pie/MeditatePieDiv + tier*MeditatePercentPerTier
}

// MeditateSaveChance is the percent chance a meditating monk shrugs off an
// affliction from an attacker of the given level.
func MeditateSaveChance(tier int, attackerLevel int, con int) int {
	chance := MeditateSaveBase + (tier-attackerLevel)*MeditateSavePerLevelDiff + (tier - MonkMeditateSaveTier) + con/MeditateSaveConDiv
	if chance > MeditateSaveCap {
		return MeditateSaveCap
	}
	if chance < 0 {
		return 0
	}
	return chance
}

// MeditateDuration is the full trance length in seconds.
func MeditateDuration(tier int) int {
	return MeditateBaseDuration + tier*MeditateDurationPerTier
}

// MeditateCharge is the share (0..1) of a full meditate recovered after the
// given number of seconds since the last cast.
func MeditateCharge(elapsed float64) float64 {
	return math.Min(math.Max(elapsed/MeditateChargeTime, 0), 1)
}

// MeditateTranceFor is the trance length in seconds at a tier and charge,
// never less than one second.
func MeditateTranceFor(tier int, charge float64) int {
	return max(1, int(math.Round(float64(MeditateDuration(tier))*charge)))
}

// TodReference is R: the chi commitment a touch of death is measured against.
func TodReference(tier int) int {
	return TodReferenceBase + tier*TodReferencePerTier
}

// TodCooldown is the touch of death cooldown in seconds at a tier.
func TodCooldown(tier int) int {
	over := tier - TodTimerScaleTier
	if over < 0 {
		over = 0
	}
	cooldown := TodTimerBase - TodTimerPerTier*over
	if cooldown < TodTimerMin {
		return TodTimerMin
	}
	return cooldown
}

// TodChanceScaleFor is the kill chance coefficient at a tier.
func TodChanceScaleFor(tier int) float64 {
	over := tier - MonkTodTier
	if over < 0 {
		over = 0
	}
	return TodChanceScale + float64(over)*TodChanceScalePerTier
}

// TodFailPercent is the share of the target's maximum hit points a landed
// touch tears out when the kill fails, interpolated between TodFailMinPercent
// and TodFailMaxPercent by the chi commitment ratio c (0..1).
func TodFailPercent(c float64) int {
	if c < 0 {
		c = 0
	}
	if c > 1 {
		c = 1
	}
	return TodFailMinPercent + int(math.Round(c*float64(TodFailMaxPercent-TodFailMinPercent)))
}

// TodKillChance is the probability (0..TodMaxChance) that a touch kills,
// given c = chi spent / R and h = the mob's remaining HP fraction.
func TodKillChance(tier int, c float64, h float64) float64 {
	c = math.Min(math.Max(c, 0), 1)
	done := 1 - math.Min(math.Max(h, 0), 1)
	chance := TodChanceScaleFor(tier) * c * done * done
	if chance > TodMaxChance {
		return TodMaxChance
	}
	return chance
}

// MonkDodgeChance is the percent chance a monk's passive dodge evades an
// attack that has already passed the normal miss roll.
func MonkDodgeChance(dex int, skill int, feinted bool) int {
	chance := MonkDodgeBase + int(math.Floor(float64(dex)*MonkDodgePerDex)) + skill*MonkDodgePerSkill
	if feinted {
		chance += FeintDodgeBonus
	}
	if chance > MonkDodgeCap {
		return MonkDodgeCap
	}
	return chance
}
